mapper.update:

COMMENT ON COLUMN ${tableName}.tenant_id IS '租户ID';
COMMENT ON COLUMN ${tableName}.factory_code IS '工厂Code';
COMMENT ON COLUMN ${tableName}.dept_code IS '部门Code';
COMMENT ON COLUMN ${tableName}.line_code IS '产线Code';
COMMENT ON COLUMN ${tableName}.sort IS '排序';
COMMENT ON COLUMN ${tableName}.del_flag IS '0不删除,1为删除';
COMMENT ON COLUMN ${tableName}.create_time IS '数据创建时间';
COMMENT ON COLUMN ${tableName}.update_time IS '数据更新时间';
COMMENT ON COLUMN ${tableName}.create_by IS '创建人';
COMMENT ON COLUMN ${tableName}.update_by IS '更新人';
COMMENT ON COLUMN ${tableName}.trigger_json IS 'PI触发时间集合';

CREATE INDEX idx_${tableName}_createTime ON ${tableName} (create_time);
CREATE INDEX idx_${tableName}_updateTime ON ${tableName} (update_time);

mapper.select:
SELECT ${field} FROM ${table} WHERE del_flag = 0 AND ${condition}

   ORDER BY ${sort}


    LIMIT #{rowsNumber}

SELECT count(1) as num FROM information_schema.TABLES
WHERE TABLE_NAME REGEXP '^mes3_basedata_[0-9]+$' and table_schema = #{dbName}
WHERE TABLE_NAME ~ '^mes3_basedata_[0-9]+$' and table_schema = 'public'

SELECT DATE_FORMAT(${timeCode}, '%Y-%m-%d %H:%i:%s') as timeCode, ${fieldCodes}
FROM ${tableCode}
where ${timeCode} >= #{searchTimeStart}
and ${timeCode} <= #{searchTimeEnd}
order by ${timeCode} asc

SELECT id, ${xFieldName} as xFieldName, ${fieldName} as fieldName
FROM ${tableName}
where del_flag = 0
    and ${timeField} >= #{searchTimeStart}
    and ${timeField} <= #{searchTimeEnd}
    and ${fieldName} is not null
    ${strSql}
order by create_time asc

SELECT DATE_FORMAT(${uniqueField}, '%Y-%m-%d') as unique_field, ${fieldName} as field_name
FROM ${tableName}
where del_flag = 0
  and ${uniqueField} >= #{searchTimeStart}
  and ${uniqueField} <= #{searchTimeEnd}
  and ${fieldName} is not null
order by ${uniqueField} asc

SELECT
    ${field}
FROM ${table} m
CROSS JOIN JSON_TABLE(
    m.trigger_json,
    '$[*]' COLUMNS (
        field VARCHAR(50) PATH '$.field',
        calculateSignalId VARCHAR(50) PATH '$.calculateSignalId',
        time DATETIME PATH '$.time'
    )
) AS jt
WHERE m.trigger_json is not null
${condition}

    ORDER BY ${sort}
